"""Database structures only; business rules belong to later stages."""
from sqlalchemy import (MetaData, Table, Column, String, Integer, Boolean, Float,
                        Text, ForeignKey, ForeignKeyConstraint, UniqueConstraint,
                        CheckConstraint, Index, text)

metadata = MetaData()

def id_column(): return Column('id', String(36), primary_key=True)
def fk(name, target, nullable=False): return Column(name, String(36), ForeignKey(target), nullable=nullable)
def timestamp(name, nullable=False): return Column(name, String(32), nullable=nullable)
def flag(name, default=False): return Column(name, Boolean(create_constraint=True, name=f'ck_{name}_bool'), nullable=False, server_default=text('1' if default else '0'))
def choice(name, *values, nullable=False, default=None):
    return Column(name, String(40), CheckConstraint(f"{name} IN ({','.join(repr(x) for x in values)})", name=f'ck_{name}_choice'), nullable=nullable, server_default=default)

departments = Table('departments', metadata, Column('code', String(16), primary_key=True), Column('label', String(80), nullable=False, unique=True))
users = Table('users', metadata, id_column(), choice('role', 'STUDENT','STAFF','ADMIN'), fk('department_id','departments.code',True), flag('confidential_capability'), flag('verified'), flag('demo'), timestamp('created_at'), Column('trust_cache', Integer, nullable=False, server_default='50'), CheckConstraint('trust_cache BETWEEN 0 AND 100'), CheckConstraint("(role = 'STAFF' AND department_id IS NOT NULL) OR (role != 'STAFF' AND department_id IS NULL)"))
verified_identities = Table('verified_identities', metadata, Column('token', String(128), primary_key=True), fk('user_id','users.id'), timestamp('created_at'), UniqueConstraint('user_id'))
verification_challenges = Table('verification_challenges', metadata, id_column(), Column('token',String(128),nullable=False), Column('otp_digest',String(128),nullable=False), timestamp('expires_at'), Column('attempts',Integer,nullable=False,server_default='0'), flag('consumed'), timestamp('last_sent'), CheckConstraint('attempts >= 0'))
sessions = Table('sessions', metadata, id_column(), Column('token_digest',String(128),nullable=False,unique=True), fk('user_id','users.id'), timestamp('expires_at'), flag('demo_operator'), Column('generation',Integer,nullable=False,server_default='0'))
locations = Table('locations', metadata, id_column(), fk('parent_id','locations.id',True), fk('department_id','departments.code',True), Column('name',String(160),nullable=False), Column('canonical_path',String(500),nullable=False,unique=True), flag('demo',True), flag('active',True))
location_aliases = Table('location_aliases', metadata, id_column(), fk('location_id','locations.id'), Column('normalized_alias',String(200),nullable=False), UniqueConstraint('location_id','normalized_alias'))
categories = Table('categories', metadata, id_column(), fk('parent_id','categories.id',True), Column('code',String(80),nullable=False), Column('label',String(160),nullable=False), flag('active',True))
Index('uq_category_sibling', text('COALESCE(parent_id, \'\')'), categories.c.code, unique=True)
issues = Table('issues', metadata, id_column(), fk('department_id','departments.code'), fk('location_id','locations.id'), fk('category_id','categories.id'), Column('subtype',String(100)), Column('failure',String(100)), Column('asset',String(160)), Column('safe_title',String(240),nullable=False), Column('safe_description',Text,nullable=False), choice('impact','MINOR','PARTIAL_DISRUPTION','COMPLETE_DISRUPTION','MAJOR_DISRUPTION'), choice('hazard','NONE','SAFETY','MEDICAL','UNCERTAIN'), choice('status','REPORTED','ACKNOWLEDGED','IN_PROGRESS','PENDING_VERIFICATION','VERIFIED_CLOSED','REOPENED','REVIEW_REQUIRED'), Column('fingerprint',String(128)), fk('recurrence_of','issues.id',True), timestamp('created_at'), timestamp('updated_at'), Column('active_unresolved_seconds',Integer,nullable=False,server_default='0'), timestamp('active_since',True), Column('version',Integer,nullable=False,server_default='1'), CheckConstraint('active_unresolved_seconds >= 0 AND version >= 1'))
Index('uq_active_issue_fingerprint', issues.c.fingerprint, unique=True, sqlite_where=text("fingerprint IS NOT NULL AND status != 'VERIFIED_CLOSED'"))
Index('ix_issues_queue', issues.c.department_id, issues.c.status, issues.c.location_id, issues.c.created_at)
reports = Table('reports', metadata, id_column(), fk('owner_id','users.id'), fk('issue_id','issues.id',True), fk('case_id','confidential_cases.id',True), choice('visibility','PUBLIC','CONFIDENTIAL','RESTRICTED',default='RESTRICTED'), Column('private_input',Text), Column('safe_extracted_fields',Text), choice('clarification_state','NONE','REQUIRED','RESOLVED',default='NONE'), timestamp('created_at'), Column('request_key',String(128),nullable=False), UniqueConstraint('owner_id','request_key'))
community_votes = Table('community_votes', metadata, id_column(), fk('issue_id','issues.id'), fk('user_id','users.id'), choice('choice','2ND','DISAGREE'), timestamp('created_at'), timestamp('updated_at'), flag('valid',True), UniqueConstraint('issue_id','user_id'))
Index('ix_community_votes_time',community_votes.c.issue_id, community_votes.c.created_at)
issue_participants = Table('issue_participants', metadata, id_column(), fk('issue_id','issues.id'), fk('user_id','users.id'), choice('source','REPORTER','SECOND','ADMIN_APPROVED'), timestamp('first_joined'), flag('valid',True), UniqueConstraint('issue_id','user_id'))
resolution_rounds = Table('resolution_rounds', metadata, id_column(), fk('issue_id','issues.id'), Column('sequence',Integer,nullable=False), timestamp('opened_at'), timestamp('deadline'), choice('state','OPEN','FINALIZED'), choice('outcome','REOPENED','VERIFIED_CLOSED','REVIEW_REQUIRED',nullable=True), timestamp('finalized_at',True), UniqueConstraint('issue_id','sequence'), CheckConstraint('sequence > 0'))
Index('uq_open_round_per_issue',resolution_rounds.c.issue_id,unique=True,sqlite_where=text("state = 'OPEN'"))
voter_eligibility = Table('voter_eligibility', metadata, fk('round_id','resolution_rounds.id'), fk('user_id','users.id'), Column('frozen_weight',Float,nullable=False), flag('valid',True), UniqueConstraint('round_id','user_id'), CheckConstraint('frozen_weight BETWEEN 0.5 AND 1.5'))
resolution_votes = Table('resolution_votes', metadata, id_column(), Column('round_id',String(36),nullable=False), Column('user_id',String(36),nullable=False), choice('choice','CONFIRM','DISPUTE'), flag('valid',True), timestamp('created_at'), timestamp('updated_at'), UniqueConstraint('round_id','user_id'), ForeignKeyConstraint(['round_id','user_id'],['voter_eligibility.round_id','voter_eligibility.user_id']))
Index('ix_resolution_votes_time',resolution_votes.c.round_id,resolution_votes.c.created_at)
trust_events = Table('trust_events', metadata, id_column(), fk('user_id','users.id'), Column('event_key',String(160),nullable=False,unique=True), Column('delta',Integer,nullable=False), Column('reason',String(200),nullable=False), Column('source_ref',String(100),nullable=False), Column('evidence_ref',String(100)), timestamp('created_at'))
confidential_cases = Table('confidential_cases', metadata, id_column(), Column('safe_content',Text,nullable=False), Column('status',String(40),nullable=False), Column('hazard',String(40),nullable=False), timestamp('created_at'), timestamp('updated_at'))
confidential_ownership = Table('confidential_ownership',metadata,fk('case_id','confidential_cases.id'),fk('user_id','users.id'),UniqueConstraint('case_id','user_id'))
issue_history = Table('issue_history',metadata,id_column(),fk('issue_id','issues.id',True),fk('case_id','confidential_cases.id',True),Column('action',String(80),nullable=False),Column('status',String(40)),Column('safe_reason',Text),timestamp('created_at'),fk('actor_id','users.id',True),CheckConstraint('(issue_id IS NOT NULL) != (case_id IS NOT NULL)'))
attachments = Table('attachments',metadata,id_column(),fk('owner_id','users.id'),fk('report_id','reports.id',True),fk('case_id','confidential_cases.id',True),choice('purpose','MAIN_COMPLAINT','SUPPORTING_EVIDENCE'),Column('safe_type',String(100),nullable=False),Column('size',Integer,nullable=False),Column('checksum',String(128),nullable=False),Column('private_storage_key',String(160),nullable=False,unique=True),Column('sanitized_key',String(160)),choice('declared_faces','YES','NO','UNSURE'),choice('declared_nsfw','YES','NO','UNSURE'),choice('declared_sensitive','YES','NO','UNSURE'),flag('public_requested'),flag('external_consent'),choice('state','QUARANTINED','PRIVATE','PENDING_REVIEW','PUBLIC_APPROVED','REJECTED'),timestamp('expires_at',True),timestamp('created_at'),timestamp('updated_at'),CheckConstraint('size >= 0'),CheckConstraint('report_id IS NULL OR case_id IS NULL'))
attachment_reviews = Table('attachment_reviews',metadata,id_column(),fk('attachment_id','attachments.id'),Column('local_face_result',String(40)),Column('review_flags',Text),fk('reviewer_id','users.id',True),Column('safe_reason',Text),timestamp('created_at'))
moderation_flags = Table('moderation_flags',metadata,id_column(),fk('issue_id','issues.id',True),fk('case_id','confidential_cases.id',True),Column('rule',String(100),nullable=False),Column('cluster_key',String(160),nullable=False,unique=True),Column('private_evidence',Text),choice('state','PENDING','DISMISSED','CONFIRMED'),Column('reason',Text),timestamp('created_at'),CheckConstraint('(issue_id IS NOT NULL) != (case_id IS NOT NULL)'))
processing_events = Table('processing_events',metadata,id_column(),fk('report_id','reports.id',True),Column('kind',String(80),nullable=False),Column('mode',String(80),nullable=False),Column('provider_label',String(100)),flag('success'),Column('error_class',String(100)),Column('latency_ms',Integer),timestamp('created_at'),CheckConstraint('latency_ms IS NULL OR latency_ms >= 0'))
audit_logs = Table('audit_logs',metadata,id_column(),Column('event',String(100),nullable=False),fk('actor_id','users.id',True),Column('target_ref',String(100)),Column('safe_reason',Text),timestamp('created_at'))
system_settings = Table('system_settings',metadata,Column('key',String(100),primary_key=True),Column('value',Text,nullable=False))
